// FUNCTION: BFME2 0x004A40DB size=313 name=?update@HijackerUpdate@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger tier=B hypothesis:Z
UpdateSleepTime HijackerUpdate::update()
{
/// @todo srj use SLEEPY_UPDATE here

	if ( ! m_update) // have not flagged for updating
	{
		return UPDATE_SLEEP_NONE;
	}

	if (m_isInVehicle)
	{
		Object *obj = getObject();

		// If hijacker has hijacked a vehicle, he needs to move along with it...
		//Continually reset position of hijacker to match the position of the target.
		Object *target = getTargetObject();
		if( target )
		{
			obj->setPosition( target->getPosition() );
			m_wasTargetAirborne = target->isSignificantlyAboveTerrain();
			m_ejectPos = *target->getPosition();
		}
		else // the car we have been "driving" is dead now, and has safely ejected us
		{
			obj->rva0028DCC4();

			if( obj->getDrawable() )
			{
				// so it is time to unhide ourselves and be a pedestrian hijacker again
				obj->getDrawable()->setDrawableHidden( false );
			}

			// We won't come back here until and unless we have hijacked another vehicle
			obj->setStatus( OBJECT_STATUS_NO_COLLISIONS, false );
			obj->maskObject( false );
			obj->setStatus( OBJECT_STATUS_UNSELECTABLE, false );

			AIUpdateInterface* ai = obj->getAI();
			if ( ai )
			{
				ai->aiIdle( CMD_FROM_AI );
			}

			if (m_wasTargetAirborne)
			{
				const ThingTemplate* putInContainerTmpl = TheThingFactory->findTemplate(((const HijackerUpdateModuleData *)getModuleData())->m_parachuteName);
				if (putInContainerTmpl)
				{
					CreateMask createMask;
					memset(&createMask, 0, sizeof(createMask));
					Object* container = TheThingFactory->newObject( putInContainerTmpl, obj->getTeam(), &createMask, (ObjectID)0 );
					container->setPosition(&m_ejectPos);
					if (container->getContain()->isValidContainerFor(obj, true, false))
					{
						container->getContain()->addToContain(obj);
					}
				}
			}

			m_targetID = (ObjectID)0;
			m_isInVehicle = false;
			m_update = false;
			m_wasTargetAirborne = false;
		}
	}
	else	// not in vehicle
	{
		m_wasTargetAirborne = false;
	}

	return UPDATE_SLEEP_NONE;
}
